/// A privately-stored application document belonging to the rider.
///
/// [url] is a short-lived signed URL generated by the backend for the
/// authenticated rider; opening it requires no bearer token and grants
/// access to this one file only.
class RiderDocument {
  const RiderDocument({
    required this.id,
    required this.type,
    required this.label,
    required this.name,
    this.url,
    this.mimeType,
    this.isImage = false,
    this.size,
  });

  final int id;
  final String type;
  final String label;
  final String name;
  final String? url;
  final String? mimeType;
  final bool isImage;
  final String? size;

  factory RiderDocument.fromJson(Map<String, dynamic> json) {
    return RiderDocument(
      id: (json['id'] as num?)?.toInt() ?? 0,
      type: json['type'] as String? ?? '',
      label: json['label'] as String? ?? '',
      name: json['name'] as String? ?? '',
      url: json['url'] as String?,
      mimeType: json['mime_type'] as String?,
      isImage: json['is_image'] as bool? ?? false,
      size: json['size'] as String?,
    );
  }
}

/// Rider profile as returned by `/api/rider/profile` and `/api/login`.
class Rider {
  const Rider({
    required this.id,
    required this.name,
    required this.email,
    required this.phone,
    this.vehicleType,
    this.licensePlate,
    this.licenseNumber,
    this.licenseExpiry,
    this.licenseStatus,
    this.licenseExpired = false,
    this.licenseExpiringSoon = false,
    this.vehicleRegistration,
    this.company,
    this.serviceArea,
    this.status,
    this.isOnline = false,
    this.canGoOnline = true,
    this.onlineBlockReason,
    this.avatar,
    this.totalDeliveries = 0,
    this.completedDeliveries = 0,
    this.failedDeliveries = 0,
    this.documents = const [],
  });

  final int id;
  final String name;
  final String email;
  final String phone;
  final String? vehicleType;
  final String? licensePlate;
  final String? licenseNumber;
  final String? licenseExpiry;
  final String? licenseStatus;
  final bool licenseExpired;
  final bool licenseExpiringSoon;
  final String? vehicleRegistration;
  final String? company;
  final String? serviceArea;
  final String? status;
  final bool isOnline;
  final bool canGoOnline;
  final String? onlineBlockReason;
  final String? avatar;
  final int totalDeliveries;
  final int completedDeliveries;
  final int failedDeliveries;
  final List<RiderDocument> documents;

  factory Rider.fromJson(Map<String, dynamic> json) {
    List<RiderDocument> docs = const [];
    if (json['documents'] is List) {
      docs = (json['documents'] as List)
          .whereType<Map<String, dynamic>>()
          .map(RiderDocument.fromJson)
          .toList();
    }
    return Rider(
      id: (json['id'] as num?)?.toInt() ?? 0,
      name: json['name'] as String? ?? '',
      email: json['email'] as String? ?? '',
      phone: json['phone'] as String? ?? '',
      vehicleType: json['vehicle_type'] as String?,
      licensePlate: json['license_plate'] as String?,
      licenseNumber: json['license_number'] as String?,
      licenseExpiry: json['license_expiry'] as String?,
      licenseStatus: json['license_status'] as String?,
      licenseExpired: json['license_expired'] as bool? ?? false,
      licenseExpiringSoon: json['license_expiring_soon'] as bool? ?? false,
      vehicleRegistration: json['vehicle_registration'] as String?,
      company: json['company'] as String?,
      serviceArea: json['service_area'] as String?,
      status: json['status'] as String?,
      isOnline: json['is_online'] as bool? ?? false,
      canGoOnline: json['can_go_online'] as bool? ?? true,
      onlineBlockReason: json['online_block_reason'] as String?,
      avatar: json['avatar'] as String?,
      totalDeliveries: (json['total_deliveries'] as num?)?.toInt() ?? 0,
      completedDeliveries:
          (json['completed_deliveries'] as num?)?.toInt() ?? 0,
      failedDeliveries: (json['failed_deliveries'] as num?)?.toInt() ?? 0,
      documents: docs,
    );
  }

  Rider copyWith({bool? isOnline, String? phone, String? vehicleType, String? licensePlate}) {
    return Rider(
      id: id,
      name: name,
      email: email,
      phone: phone ?? this.phone,
      vehicleType: vehicleType ?? this.vehicleType,
      licensePlate: licensePlate ?? this.licensePlate,
      licenseNumber: licenseNumber,
      licenseExpiry: licenseExpiry,
      licenseStatus: licenseStatus,
      licenseExpired: licenseExpired,
      licenseExpiringSoon: licenseExpiringSoon,
      vehicleRegistration: vehicleRegistration,
      company: company,
      serviceArea: serviceArea,
      status: status,
      isOnline: isOnline ?? this.isOnline,
      canGoOnline: canGoOnline,
      onlineBlockReason: onlineBlockReason,
      avatar: avatar,
      totalDeliveries: totalDeliveries,
      completedDeliveries: completedDeliveries,
      failedDeliveries: failedDeliveries,
      documents: documents,
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'email': email,
        'phone': phone,
        'vehicle_type': vehicleType,
        'license_plate': licensePlate,
        'license_number': licenseNumber,
        'license_expiry': licenseExpiry,
        'license_status': licenseStatus,
        'license_expired': licenseExpired,
        'license_expiring_soon': licenseExpiringSoon,
        'vehicle_registration': vehicleRegistration,
        'company': company,
        'service_area': serviceArea,
        'status': status,
        'is_online': isOnline,
        'can_go_online': canGoOnline,
        'online_block_reason': onlineBlockReason,
        'avatar': avatar,
        'total_deliveries': totalDeliveries,
        'completed_deliveries': completedDeliveries,
        'failed_deliveries': failedDeliveries,
        'documents': documents
            .map((d) => {
                  'id': d.id,
                  'type': d.type,
                  'label': d.label,
                  'name': d.name,
                  'url': d.url,
                  'mime_type': d.mimeType,
                  'is_image': d.isImage,
                  'size': d.size,
                })
            .toList(),
      };
}
